import json,re,bisect,collections
from pathlib import Path
root=Path.cwd();out=Path(__file__).parent;src=root/'.local/tool-tasks/opening-member-pruning-20261008/cpu-silent-elite'
entries=[]
for line in (src/'managed-perf.map').read_text().splitlines():
 a,n,name=line.split(' ',2);entries.append((int(a,16),int(n,16),name))
entries.sort();addresses=[e[0] for e in entries]
def mapped(a):
 i=bisect.bisect_right(addresses,a)-1
 return entries[i][2] if i>=0 and a<entries[i][0]+entries[i][1] else None
old=json.loads((src/'cpu-analysis.json').read_text());offset=old['currentRealtimeMinusMonotonic'];start,end=old['openingPowerLogEpoch']
scopes={name:{'count':0,'cycles':0,'leaf':collections.Counter(),'nativeNearestManaged':collections.Counter(),'inclusive':collections.Counter()} for name in ['all-snapshot','opening-snapshot','all-standpat','opening-standpat','all-fork','opening-fork','all-outside-snapshot']}
header=re.compile(r'\s*([0-9.]+):\s+(\d+)');frame=re.compile(r'\s+([0-9a-fA-F]+)\s+\((.*)\)');ts=0;period=0;frames=[]
def trim(n):return re.sub(r'\[(?:Optimized|OptimizedTier1|QuickJitted|InstrumentedTier|InstrumentedTierOptimized|Tier0)\]$','',n)
def flush():
 if not frames:return
 resolved=[mapped(a) if 'doublemapper' in d or d=='[unknown]' else None for a,d in frames];managed=[trim(n) for n in resolved if n]
 snapshot=any('[CombatSolver] CombatSolver.CombatBeamSolver::Snapshot(' in n for n in managed)
 standpat=any('::ComputeStandPat(' in n for n in managed)
 fork=any('::Fork(' in n or '::CombatSolver.Engine.Common.ICombatPredictionForkableState.Fork(' in n for n in managed)
 opening=start<=ts+offset<=end
 for name,s in scopes.items():
  if name.endswith('snapshot') and name!='all-outside-snapshot' and not snapshot:continue
  if name.endswith('standpat') and not standpat:continue
  if name.endswith('fork') and not fork:continue
  if name=='all-outside-snapshot' and snapshot:continue
  if name.startswith('opening-') and not opening:continue
  s['count']+=1;s['cycles']+=period;s['leaf'][trim(resolved[0]) if resolved[0] else frames[0][1]]+=period
  if not resolved[0]:s['nativeNearestManaged'][next((trim(n) for n in resolved[1:] if n and not n.startswith('stub')),'(unresolved)')]+=period
  for n in set(managed):s['inclusive'][n]+=period
with (src/'stacks.txt').open() as f:
 for line in f:
  m=header.match(line)
  if m:flush();ts=float(m[1]);period=int(m[2]);frames=[]
  else:
   m=frame.match(line)
   if m:frames.append((int(m[1],16),m[2]))
flush()
result={'scope':'Reanalysis of existing hardware cycles; no new requests or sampling. Canonical tier suffixes; inclusive frames overlap. Native nearest is ancestry, not operation/allocated bytes. Reuse captured clock offset, approximate phase boundaries.','source':str(src.relative_to(root)),'scopes':{}}
for name,s in scopes.items():
 o={k:v for k,v in s.items() if isinstance(v,int)}
 for k,v in s.items():
  if isinstance(v,collections.Counter):o[k]=[{'name':n,'estimatedCycles':c,'fractionWithinScope':c/s['cycles'] if s['cycles'] else 0,'fractionWholeProcess':c/old['scopes']['all-process']['cycles']} for n,c in v.most_common(90)]
 result['scopes'][name]=o
 print(name,'samples',s['count'],'whole process',round(100*s['cycles']/old['scopes']['all-process']['cycles'],3))
 for n,c in s['leaf'].most_common(10):print(round(100*c/s['cycles'],3),n)
 print('nearest-native')
 for n,c in s['nativeNearestManaged'].most_common(5):print(round(100*c/s['cycles'],3),n)
(out/'snapshot-analysis.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')

finalize.py.source:
from pathlib import Path
import json,hashlib,shutil
root=Path.cwd();task=root/'.local/tool-tasks/health-callback-guard-20261008';cpu=root/'.local/tool-tasks/snapshot-cost-attribution-20261008'
p=root/'docs/performance/health-callback-pruning-guard-20261008.json';d=json.loads(p.read_text());d['gates']=json.loads((task/'gates.json').read_text());d['deployment']=json.loads((task/'deployment.json').read_text())
assert all(v['exitCode']==0 for v in d['gates'].values())
for source in sorted(task.glob('*.py')):
 d['sourceArchive'][source.name]={'sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'source':source.read_text()}
d['finalRegression']['nonidenticalWorkCounterFields']={}
for row in d['finalRegression']['rows']:
 rs=[r for r in d['finalRegression']['records'] if r['scene']==row['scene']]
 diff={k:[r['pruneCounters'].get(k) for r in rs] for k in rs[0]['pruneCounters'] if len({json.dumps(r['pruneCounters'].get(k),sort_keys=True) for r in rs})>1}
 if diff:d['finalRegression']['nonidenticalWorkCounterFields'][row['scene']]=diff
d['finalRegression']['fixedWorkloadEqualityClaimed']=False
d['proof']['independentTrackerReachability']='Pile/history/energy notifications remain reachable after all HP bridges are removed. Inspect current-state tracker separately; native energy notification+2HP with no HP bridge passed.'
reused=[]
for path in [task/'TaskHealthSourceAdmission.cs',task/'TaskHealthUiAdmission.cs',*sorted((task/'native').glob('*.cs'))]:
 reused.append({'path':str(path.relative_to(root)),'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'sourceAlreadyArchivedIn':'docs/performance/health-event-source-admission-20261008.json or finite-health-capacity-proof-20261008.json','readOnlyExtractionNotNewDecompile':True})
d['reusedEvidence']['temporarySourceReads']=reused
cleanup=[task/'TaskHealthSourceAdmission.cs',task/'TaskHealthUiAdmission.cs',task/'native',task/'run-final-regression.py',task/'run-native.py',task/'write-report.py',task/'deploy.py',task/'finalize.py',task/'prototype-hp-bridge-only.cs.txt',task/'initial-build-final',cpu/'analyze-snapshot.py']
d['cleanup']={'status':'ArchivedBeforeDelete','ownedPaths':[str(x.relative_to(root)) for x in cleanup],'kept':'Final validated DLL, native/pure raw results, old initial results, installed-before backup and existing CPU trace/results remain ignored; all newly authored ephemeral source archived.','initialPrototypeScope':'Superseded HP-bridge-only runtime source retained in initialPrototype; old scripts reused from existing report.'}
p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n');(task/'report-data.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
for path in cleanup:
 if path.is_dir():shutil.rmtree(path)
 elif path.exists():path.unlink()
d['cleanup']['status']='Passed';d['cleanup']['removedOwnedPaths']=len(cleanup)
p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n');(task/'report-data.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'cleanup':d['cleanup']['status'],'removedOwnedPaths':len(cleanup),'deployment':d['deployment']['status'],'maxPeakRssChangePercent':d['finalRegression']['maxPeakRssChangePercent']},ensure_ascii=False),flush=True)

